select * from product

    status = 1

        and (name like concat('%', #{keyword}, '%') or description like concat('%', #{keyword}, '%'))

    and category_id = #{categoryId}
    and price >= #{minPrice}
    and price <= #{maxPrice}

order by sales_count desc, id desc
